package com.andye.warmod.silo;
import com.andye.warmod.antiair.AntiAirMissileVariant;import com.andye.warmod.item.ModItems;import com.andye.warmod.warhead.WarheadPayloadType;import java.util.Optional;import net.minecraft.world.item.Item;
public enum SiloMissileType {CONVENTIONAL_ICBM(SiloMissileRole.STRATEGIC_STRIKE,"conventional_icbm",WarheadPayloadType.CONVENTIONAL,null,true,false),NUCLEAR_ICBM(SiloMissileRole.STRATEGIC_STRIKE,"nuclear_icbm",WarheadPayloadType.NUCLEAR,null,true,false),ANTI_AIR_MK_I(SiloMissileRole.INTERCEPTOR,"anti_air_missile_mk1",null,AntiAirMissileVariant.MK_I,false,true),ANTI_AIR_MK_II(SiloMissileRole.INTERCEPTOR,"anti_air_missile_mk2",null,AntiAirMissileVariant.MK_II,false,true);private final SiloMissileRole role;private final String name;private final WarheadPayloadType payload;private final AntiAirMissileVariant variant;private final boolean requiresTarget,automatic;SiloMissileType(SiloMissileRole r,String n,WarheadPayloadType p,AntiAirMissileVariant v,boolean t,boolean a){role=r;name=n;payload=p;variant=v;requiresTarget=t;automatic=a;}public SiloMissileRole role(){return role;}public String serializedName(){return name;}public Optional<WarheadPayloadType> payloadType(){return Optional.ofNullable(payload);}public Optional<AntiAirMissileVariant> antiAirVariant(){return Optional.ofNullable(variant);}public boolean requiresStoredTarget(){return requiresTarget;}public boolean automaticTargetAcquisition(){return automatic;}public Item item(){return switch(this){case CONVENTIONAL_ICBM->ModItems.CONVENTIONAL_ICBM;case NUCLEAR_ICBM->ModItems.NUCLEAR_ICBM;case ANTI_AIR_MK_I->ModItems.ANTI_AIR_MISSILE_MK1;case ANTI_AIR_MK_II->ModItems.ANTI_AIR_MISSILE_MK2;};}}